mapper.select:
SELECT t.*, CASE WHEN t.write_off_flag='NOT' THEN '未核销' WHEN t.write_off_flag='PARTIAL' THEN '部分核销' WHEN t.write_off_flag='FULL' THEN '完全核销' END AS write_off_flag_desc FROM ( ( SELECT cc.*, c.project_id, c.contract_number, c.contract_name, fp.approval_number, fp.company_spv, (select fc.company_full_name from fnd_company fc where fc.company_id = fp.company_id) spv_company_n, c.document_category, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, hbm.bp_name, hbm.bp_code, c.currency, ( SELECT currency_name FROM fnd_currency fc WHERE fc.currency_code = c.currency ) currency_name, CASE WHEN cc.received_amount=0 THEN 'NOT' ELSE 'PARTIAL' END write_off_flag, c.company_id, null back_bank_name, null back_bank_account_num, fe.name manager_name, fou.unit_name FROM con_contract c JOIN hls_bp_master hbm ON hbm.bp_id=c.tenant_id JOIN prj_project fp ON fp.project_id = c.project_id join fnd_employee fe on fp.employee_id=fe.employee_id join fnd_org_unit fou on fou.unit_id=fp.unit_id JOIN ( SELECT f.contract_id, f.due_date, (select f.times||'/'||max(ccc.times) from con_contract_cashflow ccc where ccc.CONTRACT_ID=f.CONTRACT_ID) times_total, f.due_date AS due_date_desc, SUM(f.due_amount) due_amount, SUM(nvl(f.received_amount,0)) received_amount, SUM(nvl(f.due_amount,0) - nvl(f.received_amount,0)) surplus_amount, SUM(nvl(f.principal,0)) the_principal, SUM(nvl(f.interest,0)) the_interest, nvl(SUM( CASE WHEN f.cf_item=51 THEN f.due_amount ELSE 0 END) ,0) the_margin, nvl(SUM( CASE WHEN f.cf_item=4 THEN f.due_amount ELSE 0 END) ,0) the_consulting_service_fee, SUM(CASE WHEN f.CF_ITEM =3 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_lease_charge, SUM(CASE WHEN f.CF_ITEM =8 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_residual_value, SUM(CASE WHEN f.CF_ITEM =2 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_down_payment, SUM(CASE WHEN f.cf_item =10 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_pre_rent, SUM(CASE WHEN f.cf_item =9 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_penalty_interest FROM con_contract_cashflow f, con_contract c WHERE c.contract_id=f.contract_id AND f.cf_direction ='INFLOW' AND nvl(f.write_off_flag,'NOT') !='FULL' AND f.cf_status = 'RELEASE' AND c.contract_status in('INCEPT','SIGN','LOAN') GROUP BY f.contract_id, f.due_date, f.times) cc ON cc.contract_id=c.contract_id WHERE c.write_off_able_flag='Y' AND c.data_class = 'NORMAL') ) t
1=1 AND t.company_id=#{request.companyId}
and (t.contract_number LIKE concat('%',concat(#{contractNameOrNumber},'%') ) or t.contract_name LIKE concat('%',concat(#{contractNameOrNumber},'%') ))
and (t.bp_name LIKE concat('%',concat(#{bpNameOrCode},'%') ) or t.bp_code LIKE concat('%',concat(#{bpNameOrCode},'%') ) )
and t.approval_number LIKE concat('%',concat(#{approvalNumber},'%') )
and t.due_date >=#{dueDateFrom}
and t.company_id = #{companyId}
and t.due_date <= #{dueDateTo}
and ((month(t.due_date) = month(sysdate) and year(t.due_date) = year(sysdate)) or (t.due_amount > t.received_amount and t.due_date < sysdate))
AND t.write_off_flag in
#{item}
order by t.due_date

SELECT t1.* FROM (SELECT a.*, h.description cf_item_desc FROM hls_cashflow_type h, (SELECT hbm.bp_name, fp.project_name, c.contract_number, T.*, fou.unit_name, fou.unit_id, fp.spv_company, (select s.MEANING value_name from sys_code_value_b_v s where s.code = 'SPV_COMPANY' and s.code_value = fp.spv_company) spv_company_n FROM con_contract c JOIN hls_bp_master hbm ON hbm.bp_id = c.tenant_id JOIN prj_project fp ON fp.project_id = c.project_id JOIN fnd_employee fe ON fp.employee_id = fe.employee_id JOIN fnd_org_unit fou ON fou.unit_id = fp.unit_id JOIN (SELECT cc.contract_id, cc.cf_item, TRUNC(cc.due_date) due_date, SUM(nvl(cc.due_amount, 0)) due_amount, SUM(nvl(cc.received_amount, 0)) received_amount, (SUM(nvl(cc.due_amount, 0)) - SUM(nvl(cc.received_amount, 0))) surplus_amount FROM con_contract c, con_contract_cashflow cc WHERE c.contract_id = cc.contract_id AND cc.cf_direction = 'INFLOW' AND cc.cf_status = 'RELEASE' AND c.contract_status in ('INCEPT', 'SIGN', 'LOAN') GROUP BY cc.contract_id, cc.cf_item, cc.due_date ORDER BY cc.contract_id, cc.cf_item) t ON c.contract_id = t.contract_id) a WHERE a.cf_item = h.cf_type) t1
1=1
and t1.unit_id = #{unitId}
and t1.due_date <= #{dueDateTo}
and t1.due_date >= #{dueDateFrom}
and t1.bp_name LIKE concat('%',concat(#{bpName},'%') )
and t1.project_name LIKE concat('%',concat(#{projectName},'%') )
and t1.contract_number LIKE concat('%',concat(#{contractNumber},'%') )
and t1.surplus_amount != 0
order by t1.contract_number DESC

select v.*,(v.due_amount-v.exemption_amount) exempted_amount ,(select nvl(sum(nvl(c.due_amount,0) - nvl(c.received_amount,0)),0) from con_contract_cashflow c where c.contract_id = v.contract_id and c.cf_direction = 'INFLOW' and c.cf_status = 'RELEASE' and c.overdue_status = 'Y') overdue_amount from (select ccc.cashflow_id, ccc.contract_id, (select cc.contract_number from con_contract cc where cc.contract_id = ccc.contract_id) contract_number, (select cc.contract_name from con_contract cc where cc.contract_id = ccc.contract_id) contract_name, (select wm_concat(hls.bp_name) from hls_bp_master hls, con_contract cc where cc.contract_id=ccc.contract_id and hls.bp_id = cc.tenant_id) tenant_name, ccc.times, ccc.cf_item, (select t.description from HLS_CASHFLOW_TYPE t where t.cf_type = ccc.cf_type) cf_item_n, ccc.cf_type, ccc.cf_direction, ccc.cf_status, --ccc.due_amount, ccc.due_date, ccc.due_amount, ccc.received_amount, (ccc.due_amount - ccc.received_amount) uncollected_amount, (ccc.due_amount - ccc.received_amount) exemption_amount, --减免金额 ccc.principal, ccc.interest, ccc.generated_source_doc_line_id, (select ccc2.write_off_flag from con_contract_cashflow ccc2 where ccc2.cashflow_id = ccc.generated_source_doc_line_id) write_off_flag, (select ccc2.due_date || '日应收的' || hci.description from con_contract_cashflow ccc2,hls_cashflow_item hci where ccc2.cashflow_id = ccc.generated_source_doc_line_id and ccc2.cf_item = hci.cf_item) message from con_contract_cashflow ccc) v
v.cf_item = 9 and v.cf_direction = 'INFLOW' and v.cf_status = 'RELEASE'
and v.contract_id = #{contractId}
AND v.contract_id in #{item1}

select v.*,(v.due_amount-v.exemption_amount) exempted_amount from (select ccc.cashflow_id, ccc.contract_id, (select cc.contract_number from con_contract cc where cc.contract_id = ccc.contract_id) contract_number, (select cc.contract_name from con_contract cc where cc.contract_id = ccc.contract_id) contract_name, ccc.times, ccc.cf_item, (select t.description from HLS_CASHFLOW_TYPE t where t.cf_type = ccc.cf_type) cf_item_n, ccc.cf_type, ccc.cf_direction, ccc.cf_status, --ccc.due_amount, ccc.due_date, ccc.due_amount, ccc.received_amount, (ccc.due_amount - ccc.received_amount) uncollected_amount, (ccc.due_amount - ccc.received_amount) exemption_amount, --减免金额 ccc.principal, ccc.interest, ccc.generated_source_doc_line_id, (select ccc2.write_off_flag from con_contract_cashflow ccc2 where ccc2.cashflow_id = ccc.generated_source_doc_line_id) write_off_flag, (select ccc2.due_date || '日应收的' || hci.description from con_contract_cashflow ccc2,hls_cashflow_item hci where ccc2.cashflow_id = ccc.generated_source_doc_line_id and ccc2.cf_item = hci.cf_item) message from con_contract_cashflow ccc) v
v.cf_item = 9 and v.cf_direction = 'INFLOW' and v.cf_status = 'RELEASE'
and v.contract_id = #{contractId}

select v.* from (select c.contract_id, c.contract_number, c.contract_name, c.company_id, c.business_type, (select p.project_name from prj_project p where p.project_id =c.project_id) project_number, (select p.project_name from prj_project p where p.project_id =c.project_id) project_name, (select wm_concat(hls.bp_code) from hls_bp_master hls, prj_project_bp ppb where ppb.project_id = c.project_id and ppb.bp_type = 'TENANT' and hls.bp_id = ppb.bp_id) tenant_code, (select wm_concat(hls.bp_name) from hls_bp_master hls, prj_project_bp ppb where ppb.project_id = c.project_id and ppb.bp_type = 'TENANT' and hls.bp_id = ppb.bp_id) tenant_name, (select hbm.bp_id from hls_bp_master hbm,prj_project pp where pp.PROJECT_ID=c.PROJECT_ID and pp.MANUFACTURER_ID=hbm.BP_ID) manufacturer_name_n, (select hbm.bp_name from hls_bp_master hbm,prj_project pp where pp.PROJECT_ID=c.PROJECT_ID and pp.MANUFACTURER_ID=hbm.BP_ID) manufacturer_name, c.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = c.unit_id) unit_id_n, (select count(1) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_direction = 'INFLOW' and cf_status = 'RELEASE' and cf_item = 1) lease_times, (select count(1) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_direction = 'INFLOW' and cf_status = 'RELEASE' and write_off_flag = 'FULL') returned_times, (select count(1) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_direction = 'INFLOW' and ccc.cf_status = 'RELEASE' and ccc.overdue_status = 'Y') overdue_times, (select sum(to_date(sysdate) - to_date(ccc.due_date)) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_direction = 'INFLOW' and ccc.cf_status = 'RELEASE' and ccc.overdue_status = 'Y') overdue_days, (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_direction = 'INFLOW' and ccc.cf_status = 'RELEASE' and ccc.overdue_status = 'Y') overdue_amount, (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_direction = 'INFLOW' and ccc.cf_status = 'RELEASE' --and ccc.overdue_status = 'Y' and ccc.cf_item = 9) overdue_penalty, (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and cf_direction = 'INFLOW' and cf_status = 'RELEASE' and cf_item = 1) left_rent, (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and cf_direction = 'INFLOW' and cf_status = 'RELEASE' and cf_item = 3) deposit, (select count(1) from con_contract_cashflow ccc where ccc.contract_id = c.contract_id and ccc.cf_item = 9 and cf_direction = 'INFLOW' and cf_status = 'RELEASE' and write_off_flag != 'FULL') fine_count, c.fine_reduce_status, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CONT.RENT_PAYMENT_STATUS'and scv.VALUE != 'APPROVE_RETURN' and scv.VALUE != 'CANCEL' and scv.value = decode(c.fine_reduce_status,null,'NEW',c.fine_reduce_status)) AS fine_reduce_status_n, (select sum(ccc2.due_amount - ccc2.received_amount) from con_contract_cashflow ccc2 where ccc2.contract_id = c.contract_id and ccc2.cf_item = 1 and ccc2.cf_direction = 'INFLOW' and ccc2.cf_status = 'RELEASE') left_amount
from con_contract c) v
1=1 and v.fine_count > 0 and v.contract_number like '%PRJ%'
and v.contract_number LIKE concat('%',concat(#{contractNumber},'%'))
and v.contract_name LIKE concat('%',concat(#{contractName},'%'))
and v.tenant_name LIKE concat('%',concat(#{tenantName},'%'))
and v.overdue_times = #{overdueTimes}
and v.fine_reduce_status = #{fineReduceStatus}
and v.manufacturer_name = #{manufacturerName}
and v.contract_id = #{contractId}
